struct CTCShop {
    unsigned char _pad[0xc];
    long StockState;                            // +0x0c
    bool IsPermanentlyStocked();                // 0x007721A0
    bool IsOpeningHours();                      // 0x00773950
    void SetStockState(long state);             // 0x00773C00
};
